// src/components/Sidebar.js
import React, { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import "./Sidebar.css";

function Sidebar({ user, onLogout }) {
  const [collapsed, setCollapsed] = useState(false);
  const [gamesExpanded, setGamesExpanded] = useState(false);
  const navigate = useNavigate();
  const [hoveredDropdown, setHoveredDropdown] = useState(null);

  function handleLogoClick() {
    navigate("/dashboard");
  }

  const games = [
    { name: "Memory Game", icon: "🧠", path: "/games/memory" },
    { name: "Quiz Game", icon: "❓", path: "/games/quiz" },
    { name: "Matching Game", icon: "🎯", path: "/games/matching" },
    { name: "Puzzle Game", icon: "🧩", path: "/games/puzzle" },
    { name: "Drag & Drop", icon: "🎪", path: "/games/dragdrop" },
    { name: "Builder Game", icon: "🏗️", path: "/games/builder" },
    { name: "Reaction Game", icon: "⚡", path: "/games/reaction" }
  ];

  return (
    <aside style={{
      position: "fixed",
      left: 0,
      top: 0,
      height: "100vh",
      width: collapsed ? "80px" : "260px",
      background: "linear-gradient(180deg, #0f172a 0%, #1a1f35 100%)",
      borderRight: "1px solid rgba(148, 163, 184, 0.15)",
      display: "flex",
      flexDirection: "column",
      padding: "20px 0",
      zIndex: 1200,
      transition: "width 300ms ease",
      overflowY: "auto",
      overflowX: "hidden",
      boxShadow: "0 8px 32px rgba(139, 92, 246, 0.1)"
    }}>
      {/* Logo Section */}
      <div style={{
        display: "flex",
        alignItems: "center",
        justifyContent: collapsed ? "center" : "space-between",
        padding: collapsed ? "16px 12px" : "16px 20px",
        marginBottom: "30px",
        gap: "12px"
      }}>
        <button
          onClick={handleLogoClick}
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            background: "none",
            border: "none",
            color: "#fff",
            cursor: "pointer",
            fontWeight: "700",
            fontSize: "1rem",
            transition: "all 200ms ease",
            padding: 0,
            flexShrink: 0
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = "scale(1.05)";
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = "scale(1)";
          }}
        >
          <div style={{
            width: "40px",
            height: "40px",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: "linear-gradient(135deg, #8b5cf6 0%, #06b6d4 100%)",
            borderRadius: "10px",
            fontSize: "1.4rem",
            flexShrink: 0,
            boxShadow: "0 6px 20px rgba(139, 92, 246, 0.3)"
          }}>
            🔬
          </div>
          {!collapsed && <span style={{ fontSize: "0.95rem" }}>SciHub</span>}
        </button>

        {!collapsed && (
          <button
            onClick={() => setCollapsed(true)}
            aria-label="Toggle sidebar"
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              width: "38px",
              height: "38px",
              background: "rgba(139, 92, 246, 0.1)",
              border: "1px solid rgba(139, 92, 246, 0.3)",
              borderRadius: "8px",
              color: "#8b5cf6",
              cursor: "pointer",
              fontSize: "1rem",
              transition: "all 200ms ease",
              padding: 0
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = "rgba(139, 92, 246, 0.2)";
              e.currentTarget.style.borderColor = "rgba(139, 92, 246, 0.5)";
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = "rgba(139, 92, 246, 0.1)";
              e.currentTarget.style.borderColor = "rgba(139, 92, 246, 0.3)";
            }}
          >
            ‹
          </button>
        )}
      </div>

      {/* Navigation */}
      <nav style={{
        display: "flex",
        flexDirection: "column",
        gap: "8px",
        flex: 1,
        width: "100%",
        padding: "0 12px"
      }}>
        {/* Dashboard */}
        <NavLink
          to="/dashboard"
          className={({ isActive }) => isActive ? "active" : ""}
          style={({ isActive }) => ({
            display: "flex",
            alignItems: "center",
            gap: "12px",
            padding: collapsed ? "10px" : "10px 14px",
